#define sat(a) clamp(a, 0., 1.)

mat2 r2d(float a) { float c= cos(a), s = sin(a); return mat2(c, -s, s, c); }

float _cube(vec3 p, vec3 s)
{
    vec3 l = abs(p)-s;
    return max(l.x, max(l.y, l.z));
}

vec2 _min(vec2 a, vec2 b)
{
    if (a.x<b.x)
        return a;
    return b;
}

vec2 map(vec3 p)
{
    vec2 acc = vec2(10000.,-1.);

    float th = 0.01;
    vec3 bSz = vec3(1.);
    float box = abs(_cube(p, bSz))-th;
    box = max(box, -_cube(p-vec3(0.,-th*3.,0.), bSz));
    acc = _min(acc, vec2(box,0.));

    float flapH = bSz.z/2.;
    vec3 pFlap =p;
    pFlap.z = -abs(pFlap.z);
    pFlap -= vec3(0.,-bSz.y+.1,-bSz.z - flapH);
    pFlap.yz *= r2d(-.25);
    float flap = _cube(pFlap, vec3(bSz.x, th, flapH));
    //flap = max(flap, abs(uv.x)-.1*uv.z);
    acc = _min(acc, vec2(flap,0.));

    for (int i = 0; i < 16; ++i)
    {
        float fi = float(i);
        vec2 dir = vec2(sin(fi), cos(fi));
        float fCube = mod(fi*.1+iTime,1.5);
        float spread = pow(fCube, 0.25f);
        vec3 pos = p-vec3(mod(fi*.1,.5), fCube*fCube-2.5, 0.0)
        +vec3(dir.x, 0.0f, dir.y)*spread*.25;
        pos.xy *= r2d(fi);
        pos.xz *= r2d(fi);
        acc = _min(acc, vec2(_cube(pos, vec3(.1)), 1.));
    }

    return acc;
}

vec3 getCam(vec3 rd, vec2 uv)
{
    vec3 r = normalize(cross(rd, vec3(0.,1.,0.)));
    vec3 u = normalize(cross(rd, r));
    return normalize(rd+r*uv.x+u*uv.y);
}

vec3 trace(vec3 ro, vec3 rd, int steps)
{
    vec3 p = ro;
    for (int i = 0; i < steps; ++i)
    {
        vec2 res = map(p);
        if (res.x< 0.01)
            return vec3(res.x, distance(p, ro), res.y);
        p+=rd*res.x;
    }
    return vec3(-1.);
}

vec3 getNorm(vec3 p, float d)
{
    vec2 e = vec2(0.01,0.);
    return normalize(vec3(d)-vec3(map(p-e.xyy).x, map(p-e.yxy).x, map(p-e.yyx).x));
}

vec3 rdr(vec2 uv)
{
    vec3 col = vec3(0.941,0.337,0.600)*pow(1.-sat(length(uv)-.2),.5);
    float d= 10.;
    float t=iTime*.5;
    vec3 ro = vec3(sin(t)*d,-5.,cos(t)*d);
    vec3 ta = vec3(0.,-1.,0.);
    vec3 rd = normalize(ta-ro);

    rd = getCam(rd, uv);
    vec3 res = trace(ro, rd, 128);
    if (res.y > 0.)
    {
        vec3 p = ro+rd*res.y;
        vec3 n = getNorm(p, res.x);
        col = n*.5+.5;
        vec3 lpos = vec3(8.,-5.,5.);
        vec3 ldir = normalize(lpos-p);
        float ndotl = dot(n,ldir);
        if (res.z == 0.)
        {
            vec2 coords = p.xy*sat(abs(dot(n, vec3(0.,0.,1.))))
            +p.zy*sat(abs(dot(n, vec3(1.,0.,0.))));
            col = pow(texture(iChannel0, coords*.2).x,.025)*
            vec3(0.831,0.545,0.306)+vec3(.2)*sat(ndotl);
        }
        if (res.z == 1.0)
        {
            col = vec3(.75)+vec3(.5)*sat(ndotl);
        }

    }

    return col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.xx;

    vec3 col = rdr(uv);

    fragColor = vec4(col,1.0);
}
